class Solution {
public:
    int smallestFactorization(int num) {
        if (num < 2) return num;
        long long res = 0, mul = 1;
        for (int d = 9; d >= 2; d--) {
            while (num % d == 0) {
                res += (long long)d * mul;
                mul *= 10;
                num /= d;
            }
        }
        if (num > 1 || res > INT_MAX) return 0;
        return (int)res;
    }
};

